	matches := findingIDPattern.FindStringSubmatch(strings.TrimSpace(value))
	if len(matches) != 2 {
		return 0, false
	}
	var sequence int
	if _, err := fmt.Sscanf(matches[1], "%d", &sequence); err != nil || sequence < 1 {
		return 0, false
	}
	return sequence, true
}

